-- Lot 221 : payloads 601 a 630 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-260","moteur":"chatgpt","payload":"[RaccourcIA — /skinretouch]\n\nMISSION\nRetoucher la peau sans effacer son identité ni sa texture. Corrige localement brillances et irrégularités temporaires, conserve grain, rides et taches distinctives. Aucun changement automatique de morphologie.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Si l’image et l’intention suffisent, génère immédiatement. Ne demande rien de visible ou déjà fourni. Aucune question si le contexte suffit.\n\nEXÉCUTION\nInterviens sur les zones indiquées, conserve texture et signes permanents non demandés. Ne déclenche pas une retouche globale du visage. Reconnais le mode demandé ou déduis-le de l’alias et applique-le : Mode /blemishremove: Interviens sur les zones indiquées, conserve texture et signes permanents non demandés. Ne déclenche pas une retouche globale du visage. Mode /skinretouch: Corrige localement brillances et irrégularités temporaires, conserve grain, rides et taches distinctives. Aucun changement automatique de morphologie. Format par défaut : 4:5, haute définition. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve l’identité, la structure du visage, la carnation, l’âge apparent et les proportions corporelles, sauf changement explicitement demandé.\n\nÉVITER\nÉvite visage remplacé, peau lissée artificiellement, morphologie modifiée, doigts incorrects, pose impossible et changement ethnique. N’invente aucune donnée et n’ajoute pas automatiquement RaccourcIA, le raccourci ou une interface dans l’image.\n\nSORTIE\nProduis l’image finale. Vérifie silencieusement sujet, proportions, perspective, lumière, matières, texte et artefacts. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"eff67475a22a9a7008069b01b699769a5650a0b37086f1436e73355edc82b86e"},{"ref":"RCI-IMG-260","moteur":"claude","payload":"[RaccourcIA — /skinretouch]\n\nMISSION\nRetoucher la peau sans effacer son identité ni sa texture. Corrige localement brillances et irrégularités temporaires, conserve grain, rides et taches distinctives. Aucun changement automatique de morphologie.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Si l’image et l’intention suffisent, génère immédiatement. Ne demande rien de visible ou déjà fourni. Aucune question si le contexte suffit.\n\nEXÉCUTION\nInterviens sur les zones indiquées, conserve texture et signes permanents non demandés. Ne déclenche pas une retouche globale du visage. Reconnais le mode demandé ou déduis-le de l’alias et applique-le : Mode /blemishremove: Interviens sur les zones indiquées, conserve texture et signes permanents non demandés. Ne déclenche pas une retouche globale du visage. Mode /skinretouch: Corrige localement brillances et irrégularités temporaires, conserve grain, rides et taches distinctives. Aucun changement automatique de morphologie. Format par défaut : 4:5, haute définition. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve l’identité, la structure du visage, la carnation, l’âge apparent et les proportions corporelles, sauf changement explicitement demandé.\n\nÉVITER\nÉvite visage remplacé, peau lissée artificiellement, morphologie modifiée, doigts incorrects, pose impossible et changement ethnique. N’invente aucune donnée et n’ajoute pas automatiquement RaccourcIA, le raccourci ou une interface dans l’image.\n\nSORTIE\nProduis l’image finale. Vérifie silencieusement sujet, proportions, perspective, lumière, matières, texte et artefacts. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"d28e73d050ca8b12549075bbf25c48a2a6bf733c36ad15c056eb6fc273d1a0da"},{"ref":"RCI-IMG-260","moteur":"gemini","payload":"[RaccourcIA — /skinretouch]\n\nMISSION\nRetoucher la peau sans effacer son identité ni sa texture. Corrige localement brillances et irrégularités temporaires, conserve grain, rides et taches distinctives. Aucun changement automatique de morphologie.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Si l’image et l’intention suffisent, génère immédiatement. Ne demande rien de visible ou déjà fourni. Aucune question si le contexte suffit.\n\nEXÉCUTION\nInterviens sur les zones indiquées, conserve texture et signes permanents non demandés. Ne déclenche pas une retouche globale du visage. Reconnais le mode demandé ou déduis-le de l’alias et applique-le : Mode /blemishremove: Interviens sur les zones indiquées, conserve texture et signes permanents non demandés. Ne déclenche pas une retouche globale du visage. Mode /skinretouch: Corrige localement brillances et irrégularités temporaires, conserve grain, rides et taches distinctives. Aucun changement automatique de morphologie. Format par défaut : 4:5, haute définition. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve l’identité, la structure du visage, la carnation, l’âge apparent et les proportions corporelles, sauf changement explicitement demandé.\n\nÉVITER\nÉvite visage remplacé, peau lissée artificiellement, morphologie modifiée, doigts incorrects, pose impossible et changement ethnique. N’invente aucune donnée et n’ajoute pas automatiquement RaccourcIA, le raccourci ou une interface dans l’image.\n\nSORTIE\nProduis l’image finale. Vérifie silencieusement sujet, proportions, perspective, lumière, matières, texte et artefacts. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"c4d3400470b358aa494f4ef8a3b3359a59e356e2da94795fe55d77816725b404"},{"ref":"RCI-IMG-267","moteur":"chatgpt","payload":"[RaccourcIA — /textremove]\n\nMISSION\nSupprimer un texte intégré et reconstruire le fond. Demande quel texte retirer si plusieurs blocs sont présents. Prolonge la matière et préserve les autres inscriptions; ne supprime pas aveuglément les mentions utiles.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Retirer un texte » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Demande quel texte retirer si plusieurs blocs sont présents. Prolonge la matière et préserve les autres inscriptions; ne supprime pas aveuglément les mentions utiles. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"6ce16381b641957e5d04ec97b7a8b3ee517aefcd87187ebb5e76161b7162c9d4"},{"ref":"RCI-IMG-267","moteur":"claude","payload":"[RaccourcIA — /textremove]\n\nMISSION\nSupprimer un texte intégré et reconstruire le fond. Demande quel texte retirer si plusieurs blocs sont présents. Prolonge la matière et préserve les autres inscriptions; ne supprime pas aveuglément les mentions utiles.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Retirer un texte » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Demande quel texte retirer si plusieurs blocs sont présents. Prolonge la matière et préserve les autres inscriptions; ne supprime pas aveuglément les mentions utiles. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"32f8327f5d1ef99b64c9c9cb221130d3381fc13ea4e93b7045876590fbe133f1"},{"ref":"RCI-IMG-267","moteur":"gemini","payload":"[RaccourcIA — /textremove]\n\nMISSION\nSupprimer un texte intégré et reconstruire le fond. Demande quel texte retirer si plusieurs blocs sont présents. Prolonge la matière et préserve les autres inscriptions; ne supprime pas aveuglément les mentions utiles.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Retirer un texte » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Demande quel texte retirer si plusieurs blocs sont présents. Prolonge la matière et préserve les autres inscriptions; ne supprime pas aveuglément les mentions utiles. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"6095658882b6ba1ec02e6f2e2214ad9b5a14259356fcaf7a75a884cb208b2185"},{"ref":"RCI-IMG-035","moteur":"chatgpt","payload":"[RaccourcIA — /roomredesign]\n\nMISSION\nRepenser une piece en conservant sa structure. Change mobilier, palette et décoration ensemble, garde ouvertures et perspective. Une dimension inconnue reste une estimation, pas une cote de projet.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle direction d’aménagement veux-tu : chaleureuse, contemporaine, premium ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Redesign de pièce » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Change mobilier, palette et décoration ensemble, garde ouvertures et perspective. Une dimension inconnue reste une estimation, pas une cote de projet. Reconnais le mode demandé ou déduis-le de l’alias et applique-le : Mode /roomredesign: Change mobilier, palette et décoration ensemble, garde ouvertures et perspective. Une dimension inconnue reste une estimation, pas une cote de projet. Mode /bathroomredesign: Conserve volume et ouvertures, propose matériaux et équipements plausibles. Ne déplace pas les arrivées d’eau supposées sans signaler l’hypothèse. Mode /bedroomredesign: Hiérarchise lit, rangement et lumière, conserve circulation et dimensions connues. Ne transforme pas une contrainte de place en volume supplémentaire fictif. Mode /kitchenredesign: Conserve volume et ouvertures, organise préparation, cuisson et rangement plausiblement. Ne prétends pas valider réseaux, ventilation ou ajustement au millimètre. Mode /officeredesign: Répartis postes, échanges et rangement selon effectif et usages fournis. Maintiens accès et circulation, sans inventer une surface supplémentaire. Mode /restaurantredesign: Relie mobilier, lumière et décoration au concept confirmé, respecte accès et zones de service. Ne promet pas de capacité d’accueil non mesurée. Mode /salonredesign: Répartis accueil, postes et rangement avec distances plausibles. Les équipements doivent correspondre aux services fournis, pas à des prestations inventées. Mode /shopredesign: Compose zone d’accueil, produits phares et circulation, conserve structure et accès. N’ajoute pas de référence de vente absente sans la qualifier de décor conceptuel. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la structure, les ouvertures, la perspective, la géométrie et tous les éléments hors périmètre de la modification.\n\nÉVITER\nÉvite murs ou ouvertures déplacés sans demande, mobilier à mauvaise échelle, perspective cassée, circulation impossible et lumière incohérente. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"f43b9e7c504b4b4e9fe00a632687b60c8308b5b7bfc29fb4ed9d1d7b99366244"},{"ref":"RCI-IMG-035","mot